### __tests__/acceptance/home-render.test.ts
```ts
/**
 * @jest-environment jsdom
 */
import * as React from 'react';
import { render, screen, within, cleanup } from '@testing-library/react';
import { PILLARS, STEPS, WHY_POINTS } from '../../src/content/home';

const nodeUtil = require('util');
const g: any = globalThis as any;
if (typeof g.TextEncoder === 'undefined') g.TextEncoder = nodeUtil.TextEncoder;
if (typeof g.TextDecoder === 'undefined') g.TextDecoder = nodeUtil.TextDecoder;
g.scrollTo = jest.fn();
(window as any).scrollTo = jest.fn();
(Element.prototype as any).scrollIntoView = jest.fn();

const { MemoryRouter } = require('react-router-dom');
const { AppRoutes } = require('../../src/App');

function renderAt(path: string) {
  return render(
    React.createElement(MemoryRouter, { initialEntries: [path] }, React.createElement(AppRoutes)),
  );
}

const norm = (s: string | null | undefined) => (s || '').replace(/\s+/g, ' ').trim();

function sentenceCount(s: string): number {
  const m = s.trim().match(/[.!?](?=\s+[A-Z0-9"']|\s*$)/g);
  return m ? m.length : 0;
}

function ancestorWhere(start: Element, scope: Element, pred: (el: Element) => boolean): Element {
  let el: Element | null = start;
  while (el) {
    if (pred(el)) return el;
    if (el === scope) break;
    el = el.parentElement;
  }
  throw new Error('No ancestor matched');
}

const follows = (a: Node, b: Node) =>
  (a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING) !== 0;

afterEach(() => cleanup());

function pillarCard(main: HTMLElement, title: string, description: string): Element {
  const candidates = within(main).getAllByText(title);
  for (const c of candidates) {
    try {
      return ancestorWhere(c, main, (el) => norm(el.textContent).includes(norm(description)));
    } catch (e) {
      /* try next */
    }
  }
  throw new Error(`No pillar card for ${title}`);
}

describe('home page rendering', () => {
  test('hero h1 and buttons', () => {
    renderAt('/');
    const main = screen.getByRole('main');
    const h1 = within(main).getByRole('heading', { level: 1 });
    expect(norm(h1.textContent)).toBe('Evidence-driven AI, built for your business.');
    const hero = ancestorWhere(h1, main, (el) =>
      Array.from(el.querySelectorAll('a')).some((a) => norm(a.textContent) === 'See how we build'),
    );
    const links = Array.from(hero.querySelectorAll('a'));
    const see = links.find((a) => norm(a.textContent) === 'See how we build');
    const book = links.find((a) => norm(a.textContent) === 'Book a consultation');
    expect(see && see.getAttribute('href')).toBe('/systems');
    expect(book && book.getAttribute('href')).toBe('/contact');
  });

  test('pillar descriptions have two or three sentences', () => {
    for (const p of PILLARS) {
      const n = sentenceCount(p.description);
      expect(n).toBeGreaterThanOrEqual(2);
      expect(n).toBeLessThanOrEqual(3);
    }
  });

  test('three pillar cards with Learn more links', () => {
    renderAt('/');
    const main = screen.getByRole('main');
    const expected = [
      ['AI Enablement', '/services#enablement'],
      ['Training', '/services#training'],
      ['Custom Development', '/services#custom-development'],
    ];
    for (const [title, href] of expected) {
      const p = PILLARS.find((x) => x.title === title)!;
      const card = pillarCard(main, title, p.description);
      const learn = Array.from(card.querySelectorAll('a')).find((a) =>
        /Learn more/.test(a.textContent || ''),
      );
      expect(learn).toBeTruthy();
      expect(learn!.getAttribute('href')).toBe(href);
    }
    const learnHrefs = Array.from(main.querySelectorAll('a'))
      .filter((a) => /Learn more/.test(a.textContent || ''))
      .map((a) => a.getAttribute('href'));
    expect(learnHrefs).toEqual(expected.map((e) => e[1]));
  });

  test('How we work has four numbered steps in order, one sentence each', () => {
    for (const s of STEPS) expect(sentenceCount(s.description)).toBe(1);
    renderAt('/');
    const main = screen.getByRole('main');
    const heading = within(main).getByRole('heading', { name: 'How we work' });
    const section = ancestorWhere(heading, main, (el) =>
      STEPS.every((s) => norm(el.textContent).includes(s.description.trim())),
    );
    const els = ['Assess', 'Design', 'Build', 'Enable'].map(
      (t) => within(section as HTMLElement).getAllByText(t)[0],
    );
    for (let i = 1; i < els.length; i++) expect(follows(els[i - 1], els[i])).toBe(true);
    const text = norm(section.textContent);
    const ol = section.querySelector('ol');
    const numbered =
      (ol !== null && ol.querySelectorAll('li').length === 4) ||
      /1[\s\S]*Assess[\s\S]*2[\s\S]*Design[\s\S]*3[\s\S]*Build[\s\S]*4[\s\S]*Enable/.test(text);
    expect(numbered).toBe(true);
  });

  test('Why The Bayes Group section covers the four points', () => {
    renderAt('/');
    const main = screen.getByRole('main');
    const heading = within(main).getByRole('heading', { name: 'Why The Bayes Group' });
    const section = ancestorWhere(heading, main, (el) =>
      WHY_POINTS.every((w) => norm(el.textContent).includes(norm(w.title))),
    );
    const text = norm(section.textContent).toLowerCase();
    expect(text).toContain('credentialed');
    expect(text).toContain('data scientist');
    expect(text).toMatch(/hands-on|builder/);
    expect(text).toMatch(/vendor[- ]neutral/);
    expect(text).toContain('transfer');
    expect(text).toMatch(/\bowns?\b/);
  });

  test('sections appear in order and the page ends with the CTA band', () => {
    renderAt('/');
    const main = screen.getByRole('main');
    const h1 = within(main).getByRole('heading', { level: 1 });
    const pillar = pillarCard(main, PILLARS[0].title, PILLARS[0].description);
    const how = within(main).getByRole('heading', { name: 'How we work' });
    const why = within(main).getByRole('heading', { name: 'Why The Bayes Group' });
    const cta = within(main).getByRole('heading', { name: 'Ready to put AI to work?' });
    const order = [h1, pillar, how, why, cta];
    for (let i = 1; i < order.length; i++) expect(follows(order[i - 1], order[i])).toBe(true);

    const headings = main.querySelectorAll('h1, h2, h3, h4, h5, h6');
    expect(headings[headings.length - 1]).toBe(cta);
    const links = main.querySelectorAll('a');
    const last = links[links.length - 1];
    expect(norm(last.textContent)).toBe('Book a consultation');
    expect(last.getAttribute('href')).toBe('/contact');
    expect(follows(cta, last)).toBe(true);
  });
});
```

### __tests__/acceptance/navigation-render.test.ts
```ts
/**
 * @jest-environment jsdom
 */
import * as React from 'react';
import { render, screen, within, cleanup, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

const nodeUtil = require('util');
const g: any = globalThis as any;
if (typeof g.TextEncoder === 'undefined') g.TextEncoder = nodeUtil.TextEncoder;
if (typeof g.TextDecoder === 'undefined') g.TextDecoder = nodeUtil.TextDecoder;

const { MemoryRouter } = require('react-router-dom');
const { AppRoutes } = require('../../src/App');

let intoView: Element[] = [];

beforeEach(() => {
  intoView = [];
  g.scrollTo = jest.fn();
  (window as any).scrollTo = g.scrollTo;
  (Element.prototype as any).scrollIntoView = function (this: Element) {
    intoView.push(this);
  };
});

afterEach(() => cleanup());

function renderAt(path: string) {
  return render(
    React.createElement(MemoryRouter, { initialEntries: [path] }, React.createElement(AppRoutes)),
  );
}

const norm = (s: string | null | undefined) => (s || '').replace(/\s+/g, ' ').trim();

function scrolledToTop(fn: any): boolean {
  return fn.mock.calls.some(
    (a: any[]) =>
      (a[0] === 0 && (a[1] === 0 || a[1] === undefined)) ||
      (a[0] !== null && typeof a[0] === 'object' && a[0].top === 0),
  );
}

describe('route change scroll and focus', () => {
  test('first page load does not scroll or move focus', () => {
    renderAt('/');
    const main = screen.getByRole('main');
    expect((window as any).scrollTo).not.toHaveBeenCalled();
    expect(intoView).toHaveLength(0);
    expect(document.activeElement).not.toBe(main);
  });

  test('first page load with a hash does not scroll', () => {
    renderAt('/services#training');
    expect((window as any).scrollTo).not.toHaveBeenCalled();
    expect(intoView).toHaveLength(0);
  });

  test('navigating to another page scrolls to the top and focuses main', async () => {
    const user = userEvent.setup();
    renderAt('/');
    const main = screen.getByRole('main');
    const see = Array.from(main.querySelectorAll('a')).find(
      (a) => norm(a.textContent) === 'See how we build' && a.getAttribute('href') === '/systems',
    );
    expect(see).toBeTruthy();
    await user.click(see!);
    await waitFor(() =>
      expect(norm(within(screen.getByRole('main')).getByRole('heading', { level: 1 }).textContent)).toBe(
        'Systems engineering',
      ),
    );
    await waitFor(() => expect(scrolledToTop((window as any).scrollTo)).toBe(true));
    await waitFor(() => {
      const m = screen.getByRole('main');
      expect(m.id).toBe('main');
      expect(document.activeElement).toBe(m);
    });
  });

  test('navigating with a footer link also scrolls and focuses main', async () => {
    const user = userEvent.setup();
    renderAt('/services');
    const footer = screen.getByRole('contentinfo');
    const about = within(footer)
      .getAllByRole('link', { name: 'About', hidden: true })
      .find((a) => a.getAttribute('href') === '/about');
    expect(about).toBeTruthy();
    await user.click(about!);
    await waitFor(() =>
      expect(norm(within(screen.getByRole('main')).getByRole('heading', { level: 1 }).textContent)).toBe('About'),
    );
    await waitFor(() => expect(scrolledToTop((window as any).scrollTo)).toBe(true));
    await waitFor(() => expect(document.activeElement).toBe(screen.getByRole('main')));
  });

  test('a link with a hash scrolls to that section', async () => {
    const user = userEvent.setup();
    renderAt('/');
    const main = screen.getByRole('main');
    const learn = Array.from(main.querySelectorAll('a')).find(
      (a) => a.getAttribute('href') === '/services#training',
    );
    expect(learn).toBeTruthy();
    await user.click(learn!);
    await waitFor(() => expect(document.getElementById('training')).not.toBeNull());
    await waitFor(() => {
      const ids = intoView.map((e) => e.id);
      if (!ids.includes('training')) {
        throw new Error(`Expected scrollIntoView on #training, got calls on: ${JSON.stringify(ids)}`);
      }
    });
  });
});
```

### __tests__/acceptance/layout-render.test.ts
```ts
/**
 * @jest-environment jsdom
 */
import * as React from 'react';
import { render, screen, within, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

const nodeUtil = require('util');
const g: any = globalThis as any;
if (typeof g.TextEncoder === 'undefined') g.TextEncoder = nodeUtil.TextEncoder;
if (typeof g.TextDecoder === 'undefined') g.TextDecoder = nodeUtil.TextDecoder;
g.scrollTo = jest.fn();
(window as any).scrollTo = jest.fn();
(Element.prototype as any).scrollIntoView = jest.fn();

const { MemoryRouter } = require('react-router-dom');
const { AppRoutes } = require('../../src/App');

function renderAt(path: string) {
  return render(
    React.createElement(MemoryRouter, { initialEntries: [path] }, React.createElement(AppRoutes)),
  );
}

const norm = (s: string | null | undefined) => (s || '').replace(/\s+/g, ' ').trim();

afterEach(() => cleanup());

const NAV: Array<[string, string]> = [
  ['Services', '/services'],
  ['Systems', '/systems'],
  ['Training', '/training'],
  ['Engagements', '/engagements'],
  ['About', '/about'],
  ['Contact', '/contact'],
];

const ROUTES: Array<[string, string, string]> = [
  ['/', 'The Bayes Group | Evidence-driven AI', 'Evidence-driven AI, built for your business.'],
  ['/services', 'Services | The Bayes Group', 'Services'],
  ['/systems', 'Systems engineering | The Bayes Group', 'Systems engineering'],
  ['/training', 'Training | The Bayes Group', 'Training'],
  ['/engagements', 'Engagements | The Bayes Group', 'Engagements'],
  ['/about', 'About | The Bayes Group', 'About'],
  ['/contact', 'Contact | The Bayes Group', 'Book a consultation'],
  ['/this-page-does-not-exist', 'Page not found | The Bayes Group', 'Page not found'],
];

describe.each(ROUTES)('page %s', (path, title, h1Text) => {
  test('sets the document title', () => {
    document.title = '';
    renderAt(path);
    expect(document.title).toBe(title);
  });

  test('has exactly one h1 with the expected text', () => {
    const { container } = renderAt(path);
    const h1s = container.querySelectorAll('h1');
    expect(h1s).toHaveLength(1);
    expect(norm(h1s[0].textContent)).toBe(h1Text);
  });

  test('uses header, nav, main and footer landmarks', () => {
    renderAt(path);
    const banner = screen.getByRole('banner');
    expect(banner.tagName).toBe('HEADER');
    expect(banner.querySelector('nav')).not.toBeNull();
    expect(screen.getAllByRole('main')).toHaveLength(1);
    expect(screen.getByRole('main').tagName).toBe('MAIN');
    expect(screen.getByRole('contentinfo').tagName).toBe('FOOTER');
  });

  test('header has the wordmark home link, nav links and the CTA', () => {
    renderAt(path);
    const banner = screen.getByRole('banner');
    const homeLinks = within(banner)
      .getAllByRole('link', { name: /The Bayes Group/, hidden: true })
      .filter((a) => a.getAttribute('href') === '/');
    expect(homeLinks.length).toBeGreaterThan(0);
    expect(homeLinks[0].querySelector('svg')).not.toBeNull();
    for (const [label, to] of NAV) {
      const links = within(banner).getAllByRole('link', { name: label, hidden: true });
      expect(links.some((a) => a.getAttribute('href') === to)).toBe(true);
    }
    const cta = within(banner).getAllByRole('link', { name: 'Book a consultation', hidden: true });
    expect(cta.some((a) => a.getAttribute('href') === '/contact')).toBe(true);
  });

  test('footer has the wordmark, line, nav links and copyright', () => {
    renderAt(path);
    const footer = screen.getByRole('contentinfo');
    expect(footer.querySelector('svg')).not.toBeNull();
    const text = norm(footer.textContent);
    expect(text).toContain('The Bayes Group');
    expect(text).toContain('AI enablement, training and custom development.');
    expect(text).toContain('\u00a9 2026 The Bayes Group');
    for (const [label, to] of NAV) {
      const links = within(footer).getAllByRole('link', { name: label, hidden: true });
      expect(links.some((a) => a.getAttribute('href') === to)).toBe(true);
    }
  });
});

describe('mobile menu', () => {
  test('Menu button opens and closes the navigation links', async () => {
    const user = userEvent.setup();
    renderAt('/');
    const banner = screen.getByRole('banner');
    const btn = within(banner).getByRole('button', { name: /menu/i });
    expect(btn.getAttribute('aria-expanded')).toBe('false');
    const controlsId = btn.getAttribute('aria-controls');
    expect(controlsId).toBeTruthy();

    await user.click(btn);
    expect(btn.getAttribute('aria-expanded')).toBe('true');
    const panel = document.getElementById(controlsId as string);
    expect(panel).not.toBeNull();
    for (const [label, to] of NAV) {
      const link = within(panel as HTMLElement).getByRole('link', { name: label });
      expect(link.getAttribute('href')).toBe(to);
    }
    const cta = within(panel as HTMLElement).getByRole('link', { name: 'Book a consultation' });
    expect(cta.getAttribute('href')).toBe('/contact');

    await user.click(btn);
    expect(btn.getAttribute('aria-expanded')).toBe('false');
  });
});

describe('not found page', () => {
  test('unknown route shows Page not found with a link home', () => {
    renderAt('/no/such/page');
    const main = screen.getByRole('main');
    expect(within(main).getByRole('heading', { level: 1 }).textContent).toBe('Page not found');
    const homeLinks = Array.from(main.querySelectorAll('a')).filter(
      (a) => a.getAttribute('href') === '/',
    );
    expect(homeLinks.length).toBeGreaterThan(0);
  });
});
