      .filter((f) => f.endsWith('.css'))
      .map((f) => fs.readFileSync(path.join(ROOT, 'src', 'styles', f), 'utf8'))
      .join('\n');
    expect(css).toMatch(/scroll-margin-top\s*:/);
  });
});

